        /// <returns></returns>
        public override ReportingColumnAsync? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            string? rawValue = reader.GetString();

            ReportingColumnAsync? result = rawValue == null
                ? null
                : ReportingColumnAsyncValueConverter.FromStringOrDefault(rawValue);

            if (result != null)
                return result.Value;

            throw new JsonException();
        }

        /// <summary>
        /// Writes the DateTime to the json writer
        /// </summary>
        /// <param name="writer"></param>
        /// <param name="reportingColumnAsync"></param>
        /// <param name="options"></param>
        public override void Write(Utf8JsonWriter writer, ReportingColumnAsync? reportingColumnAsync, JsonSerializerOptions options)
        {
            writer.WriteStringValue(reportingColumnAsync?.ToString() ?? "null");
        }
    }
